  "originalFormula": "V_{DS(sat)} = V_{GS} - V_{T} = 1.0 - 0.4 = 0.6 \, \\text{V}",
  "genericFormula": "V_{DS(sat)} = V_{GS} - V_{T}",
  "description": "Esta fórmula representa a tensão de dreno-sourcce em saturação de um transistor de efeito de campo (FET). Ela mostra a relação entre a tensão de gate-source, a tensão de limiar e a tensão de dreno-source quando o transistor está operando na região de saturação.",
  "concepts": [
    "Transistor de efeito de campo (FET)",
    "Tensão de dreno-source em saturação",
    "Tensão de gate-source",
    "Tensão de limiar"
  ],
  "symbols": [
    {
      "symbol": "V_{DS(sat)}",
      "description": "Representa a tensão entre o dreno e a fonte do transistor quando ele está na região de saturação."
    },
    {
      "symbol": "V_{GS}",
      "description": "Representa a tensão aplicada entre o gate e a fonte do transistor."
    },
    {
      "symbol": "V_{T}",
      "description": "Representa a tensão de limiar, que é a tensão mínima necessária para que o transistor comece a conduzir."
    }
  ]
}
